SELECT u.id, u.username, uf.created_at AS followedAt
FROM user_follows uf
JOIN users u ON uf.follower_id = u.id
WHERE uf.following_id = #{userId}
ORDER BY uf.created_at DESC
LIMIT #{limit} OFFSET #{offset}

